export function lateFee(invoice, asOf) {
  if (!invoice || invoice.status === 'draft') {
    return 0;
  }

  if (!invoice.dueDate) {
    return 0;
  }

  const dueDateObj = new Date(invoice.dueDate + 'T00:00:00Z');
  const asOfObj = new Date(asOf + 'T00:00:00Z');
  const daysOverdue = Math.floor((asOfObj - dueDateObj) / (1000 * 60 * 60 * 24));

  if (daysOverdue <= 0) {
    return 0;
  }

  const totalsResult = invoiceTotals(invoice);
  const amountDue = totalsResult.ok ? totalsResult.value.total : 0;

  const dailyRate = 0.0004;
  const fee = amountDue * dailyRate * daysOverdue;

  return roundCents(fee);
}

export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  const customerDueMap = new Map();
  let outstanding = 0;

  for (const invoice of invoices) {
    counts[invoice.status] = (counts[invoice.status] ?? 0) + 1;

    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      const due = balanceDue(invoice);
      outstanding += due;

      if (!customerDueMap.has(invoice.customerId)) {
        customerDueMap.set(invoice.customerId, 0);
      }
      customerDueMap.set(invoice.customerId, customerDueMap.get(invoice.customerId) + due);
    }
  }

  const overduList = overdueInvoices(invoices, asOf);
  let overdueAmount = 0;
  for (const item of overduList) {
    overdueAmount += item.due;
  }

  const topCustomers = Array.from(customerDueMap, ([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: {
      count: overduList.length,
      amount: overdueAmount,
    },
    topCustomers,
  };
}

